//
// 梯度光照渲染算法
// https://ddzeb.com/blog/post#77/gradient-based-lighting
//
vec3 gradLight(vec3 col, vec2 grad, float depth) {
  vec3 n = normalize(vec3(grad, depth));
  const vec3 l = normalize(vec3(1, 1, 2));
  float diff = clamp(dot(n, l), .5, 1.);
  float spec = clamp(dot(reflect(l, n), vec3(0, 0, -1)), 0., 1.);
  return col * diff + pow(spec, 36.);
}

vec2 texGrad(sampler2D sampler, vec2 uv, float delta) {
  vec2 d = vec2(delta, 0);
  vec4 c0 = texture(sampler, uv + d.xy);
  vec4 c1 = texture(sampler, uv - d.xy);
  vec4 c2 = texture(sampler, uv + d.yx);
  vec4 c3 = texture(sampler, uv - d.yx);
  return vec2( // use length of the color components as the coordinate value
    length(c0.rgb) - length(c1.rgb),
    length(c2.rgb) - length(c3.rgb)
  );
}

void mainImage( out vec4 fragColor, in vec2 fragCoord ) {
  // uv11
  vec2 uv = fragCoord / iResolution.xy;

  // grad light shading
  vec3 col = texture(iChannel0, uv).rgb;
  vec2 grad = texGrad(iChannel0, uv, 1e-2);
  col = gradLight(col, grad, 1.0);

  // output to screen
  fragColor = vec4(col, 1.0);
}

