#define PI 3.14159265358979323846

// logarithmic polar transform
// https://ddzeb.com/lands#demo-109
vec2 logPolar(vec2 p) {
  return vec2(atan(p.y, p.x), log(length(p))) / PI;
}

//
// triangle wave, return value within [-1, +1)
// https://ddzeb.com/lands#clip-29
//
#define triWave(x) (abs(fract(((x)-1.0)*0.25)-0.5)*4.0-1.0)

//
// hash function
//
float hashFra1(vec2 v) { 
  float n = v.x + 317.0 * v.y;
  return fract(n * 17.0 * fract(n * 0.3183099));
}

//
// 2D fbm
//
float fbm2(vec2 p) {
  float a = 1.0, r = 0.0, s = 0.0, f = 1.0, n;
  vec2 nx, ni, nf;

  for (int i = 1; i < 4 ; ++i) {
    nx = p * f;

    ni = floor(nx); 
    nf = nx - ni; 
    nf = nf * nf * (3.0 - 2.0 * nf);
    n = mix(
      mix(hashFra1(ni+vec2(0,0)), hashFra1(ni+vec2(1,0)), nf.x), 
      mix(hashFra1(ni+vec2(0,1)), hashFra1(ni+vec2(1,1)), nf.x), 
      nf.y
    );

    r += n * a;
    s += a;

    a *= 0.5;
    f *= 2.0;
    p += 1.0;
  }

  return r / s;
}


vec3 render(vec2 p) {
  // scaled distane
  float d = length(p) * 15.;

  // log-polar transform
  p = logPolar(p);

  // phasing
  p += vec2(.03, .05) * iTime;

  // stitching
  p.x = triWave(p.x * 2.0) * 0.5;

  // fbm noise
  float v = fbm2(p * 15.);

  // darken the singularity points, cheap anti-aliasing
  v = mix(v, 0.0, 1.0 / (1.0 + d * 0.1 + d * d * 2.0));

  // tint
  return v * vec3(0.2, 0.7, 0.9);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord ) {
  // uvx2
  vec2 uv = (fragCoord * 2.0 - iResolution.xy) / iResolution.x;

  // render
  vec3 col = render(uv);

  // output to screen
  fragColor = vec4(col, 1.0);
}
